insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 1, 'En el mes séptimo, a veintiún días del mes, habló el Señor al profeta Ageo, diciéndole:');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 2, 'Habla a Zorobabel, hijo de Salatiel, gobernador de Judá, y a Josué, hijo de Josedec, sumo sacerdote, y al resto del pueblo, y diles:');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 3, '¿Quién ha quedado de todos vosotros que haya visto este templo en su gloria primera? ¿Y qué tal os parece él ahora? ¿Por ventura no es como nada ante vuestros ojos?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 4, 'Pues ahora, ¡oh Zorobabel!, ten buen ánimo, dice el Señor, buen ánimo también, ¡oh Josué, hijo de Josedec, sumo sacerdote; y buen ánimo tú, pueblo todo del país!, dice el Señor de los ejércitos, y cumplid, pues yo estoy con vosotros, dice el Señor de los ejércitos,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 5, 'el pacto que hice con vosotros cuando salíais de la tierra de Egipto');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 6, 'Porque esto dice el Señor de los ejércitos: Aún falta poco tiempo y yo pondré en movimiento el cielo y la tierra, y el mar y todo el universo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 7, 'Y pondré en movimiento las gentes todas, porque vendrá el deseado de todas las gentes; y henchiré de gloria este templo, dice el Señor de los ejércitos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 8, 'Por lo demás mía es la plata, dice el Señor de los ejércitos, y mío el oro.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 9, 'La gloria de este último templo será grande, será mayor que la del primero, dice el Señor de los ejércitos, y en este lugar daré yo la paz o felicidad, dice el mismo Señor de los ejércitos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 10, 'A veinticuatro días del mes noveno, en el año segundo del rey Darío, el Señor habló al profeta Ageo, y le dijo:');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 11, 'Esto dice el Señor de los ejércitos: Propón a los sacerdotes esta cuestión legal:');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 12, 'Si un hombre llevare carne santificada en una extremidad de su vestido, y tocare con la orla de él pan o vianda, o vino, o aceite, u otra cosa de comer, ¿quedará acaso santificada la tal cosa? Y respondieron los sacerdotes, y dijeron: No.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 13, 'Y añadió Ageo: Si alguno que está inmundo por razón de un muerto tocare alguna de todas estas cosas, ¿quedará por ventura inmunda la cosa que tocó? Y respondieron los sacerdotes diciendo: Inmunda quedará.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 14, 'A lo que repuso Ageo, y dijo: Así es este pueblo, y así es esta gente delante de mí, dice el Señor, y así sucede con todas las obras de sus manos; pues todo cuanto han ofrecido en este lugar, todo es inmundo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 15, 'Y reflexionad ahora vosotros lo sucedido desde este día atrás, antes que comenzaseis a construir el templo del Señor,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 16, 'cuando acercándoos a un montón de mieses, que parecía de veinte celemines, venía a quedar en diez; y yendo al lagar para sacar cincuenta cántaros, no sacabais más de veinte,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 17, 'yo destruí con viento abrasador, y con plagas, y con pedrisco todas las labores de vuestras manos; y no hubo entre vosotros quien se convirtiese a mí, dice el Señor.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 18, 'Pero fijad vuestra atención desde este día en adelante, desde el día veinticuatro del mes noveno, desde el día en que se echaron los cimientos del templo del Señor, parad vuestra atención.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 19, '¿No veis cómo aún no han nacido las simientes, y que las viñas, y las higueras, y los granados, y los olivos no están en flor? Pues yo desde este día les echaré mi bendición.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 20, 'Y habló el Señor por segunda vez a Ageo, a los veinticuatro días del mes y le dijo:');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 21, 'Habla a Zorobabel, gobernador de Judá, y dile: Yo pondré en movimiento a un tiempo el cielo y la tierra,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 22, 'y trastornaré el trono de los reinos, y destruiré el poder del reino de las gentes, y volcaré los carros de guerra, y los que van sobre ellos, y caerán muertos los caballos y los que los montan, cada uno bajo el filo de la espada de su hermano.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('aggeus', 2, 23, 'En aquel tiempo, dice el Señor de los ejércitos, yo te ensalzaré, ¡oh Zorobabel, hijo de Salatiel, siervo mío!, dice el Señor, y te tendré como un anillo de sellar; pues a ti te he escogido, dice el Señor de los ejércitos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 1, 'Más vale la buena reputación que los más preciosos perfumes');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 2, 'Mejor es ir a la casa del luto que a la casa del festín; pues en aquélla se recuerda el paradero de todos los hombres, y el que vive considera lo que le ha de suceder un día.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 3, 'Mejor es el enojo del justo que la falsa risa del lisonjero; porque con la tristeza del semblante del justo, se corrige el corazón del pecador.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 4, 'Y así el corazón de los sabios está contento en la casa donde hay tristeza, y el corazón de los necios donde hay diversión.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 5, 'Más vale ser reprendido del sabio que seducido con las lisonjas de los necios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 6, 'Porque las risas o aplausos del insensato son como el vano ruido de las espinas cuando arden debajo de la olla');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 7, 'La calumnia conturba aún al sabio y le hace perder la fortaleza de su corazón.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 8, 'Mejor es el fin de un discurso o negocio, que el principio. Mejor es el hombre sufrido que el arrogante.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 9, 'No seas, pues, fácil en airarte, porque la ira se abriga en el corazón del insensato.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 10, 'No digas nunca: ¿De qué proviene que los tiempos pasados fueron mejores que los de ahora?, pues es esta una pregunta necia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 11, 'La sabiduría con riquezas es más útil, y aprovecha más a los otros hombres.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 12, 'Porque como la sabiduría es un escudo, así lo es el dinero; pero la instrucción y la sabiduría de Dios tienen la ventaja de que dan vida a quien las posee.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 13, 'Considera las obras de Dios, y que ninguno puede corregir o enderezar a quien él ha dejado de su mano.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 14, 'Tú, pues, en el día que tengas bueno, goza del bien, y prevente para pasar con paciencia el día malo; porque como Dios ha hecho aquél, así ha hecho éste; sin que ningún hombre tenga justo motivo para quejarse.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 15, 'He visto así mismo en los caducos y frágiles días de mi vida que perece el justo en medio de su justicia, y el impío vive largo tiempo en medio de su malicia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 16, 'No quieras ser demasiado justo, ni saber más de lo que conviene, no sea que vengas a parar en estúpido.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 17, 'No multipliques pecados sobre pecados, ni quieras ser insensato difiriendo la enmienda; no sea que te coja la muerte antes de tiempo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 18, 'Bueno es que socorras al justo');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 19, 'La sabiduría hace al sabio más fuerte que diez o muchos poderosos de una ciudad');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 20, 'porque no hay hombre justo en la tierra que haga el bien y no peque jamás.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 21, 'No te pares a escuchar todas las conversaciones que se tienen, no sea que oigas a tu siervo murmurar a ti,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 22, 'ya que tu conciencia te atestigua que tú también has murmurado frecuentemente de otros.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 23, 'Yo hice todo lo posible por alcanzar la sabiduría. Dije para conmigo: Yo he de llegar a ser sabio. Pero ella se desvió lejos de mí');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 24, 'mucho más que antes. ¡Oh, cuán grande es su profundidad! ¿Quién podrá llegar a sondearla?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 25, 'Recorrió mi espíritu todas las cosas para saber y considerar, y buscar la sabiduría y la razón, para conocer asimismo la malicia de los insensatos y el error de los imprudentes;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 26, 'y hallé al fin que es más amarga que la muerte la mujer; la cual es un lazo de cazar, y una red barredera su corazón, y sus manos unos grillos. Quien es grato a Dios huirá y se librará de ella; pero el pecador quedará preso.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 27, 'Esto es lo que hallé, dijo el Eclesiastés, habiendo recorrido una cosa tras otra, para averiguar la razón de la pérdida de tantos hombres;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 28, 'razón que aún anda buscando mi alma, sin haberla podido descubrir; a saber, porque entre mil hombres hallé uno, y ninguna entre las mujeres todas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiastes', 7, 29, 'Sólo esto hallé: que Dios creó al hombre recto, y el mismo hombre se enredó en infinitas cuestiones y peligros. ¿Quién es igual al sabio? ¿Quién conoce la solución de esta difícil parábola?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('jonas', 2, 1, 'E hizo Jonás oración al Señor Dios suyo desde el vientre del pez');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('jonas', 2, 2, 'y después dijo: He invocado al Señor en medio de mi tribulación, y me ha escuchado benigno: he clamado desde el seno del sepulcro, y tú, ¡oh Señor!, has atendido mi voz.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('jonas', 2, 3, 'Y me arrojaste a lo más profundo del mar, y me rodearon las aguas, sobre mí han pasado todos tus remolinos y todas tus olas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('jonas', 2, 4, 'Y dije: He sido arrojado lejos de la misericordiosa vista de tus ojos. Pero no');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('jonas', 2, 5, 'Me cercaron las aguas hasta el punto de quitarme la vida; encerrado me he visto en el abismo, el inmenso piélago ha cubierto mi cabeza.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('jonas', 2, 6, 'He descendido hasta las raíces de los montes; los cerrojos o barreras de la tierra me encerraron allí dentro para siempre, mas tú, ¡oh Señor Dios mío!, sacarás mi vida, o alma, del lugar de la corrupción.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('jonas', 2, 7, 'En medio de las angustias que padecía mi alma, he recurrido a ti, ¡oh Señor!, dirigiéndote mi oración al templo santo de tu gloria.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('jonas', 2, 8, 'Aquellos que tan inútilmente se entregan a la vanidad de los ídolos, abandonan tu misericordia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('jonas', 2, 9, 'Mas yo te ofreceré en sacrificio cánticos de alabanza');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('jonas', 2, 10, 'El Señor, en fin, dio la orden al pez, y éste vomitó a Jonás en la ribera.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 1, 'donde habló el Señor a Moisés, diciendo:');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 2, 'Envía sujetos principales, uno de cada tribu, a registrar la tierra de Canaán, la cual tengo de dar a los hijos de Israel.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 3, 'Hizo Moisés lo que mandaba el Señor, enviando desde el desierto de Farán algunos varones principales cuyos nombres son estos:');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 4, 'De la tribu de Rubén, Sammua, hijo de Zecur.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 5, 'De la tribu de Simeón, Safat, hijo de Huri.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 6, 'De la tribu de Judá, Caleb, hijo de Jefone.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 7, 'De la tribu de Isacar, Igal, hijo de José.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 8, 'De la tribu de Efraín, Oseas, hijo de Nun.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 9, 'De la tribu de Benjamín, Falti, hijo de Rafu.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 10, 'De la tribu de Zabulón, Geddiel, hijo de Sodi.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 11, 'De la tribu de José, por la estirpe de Manasés, Gaddi, hijo de Susi.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 12, 'De la tribu de Dan, Ammiel, hijo de Gemalli.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 13, 'De la tribu de Aser, Stur, hijo de Micael.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 14, 'De la tribu de Neftalí, Nahabí, hijo de Vapsi.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 15, 'De la tribu de Gad, Güel, hijo de Maqui.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 16, 'Estos son los nombres de los sujetos que envió Moisés a reconocer la tierra; y a Oseas, hijo de Nun, le dio el nombre de Josué.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 17, 'Los envió, pues, Moisés a reconocer la tierra de Canaán, y les dijo: Subid por la parte del mediodía, y llegando a los montes,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 18, 'reconoced la tierra qué tal es; y el pueblo que habita en ella, si es fuerte o flaco, si pocos en número o muchos,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 19, 'si la tierra en sí misma es buena o mala: qué tales las ciudades, si están muradas o sin muros;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 20, 'si el terreno es estéril, si de bosques o sin árboles. Tened buen ánimo y traednos de los frutos de la tierra. Era entonces el tiempo en que ya se pueden comer las uvas tempranas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 21, 'Habiendo, pues, partido, exploraron la tierra desde el desierto de Tsin hasta Rohob a la entrada de Emat.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 22, 'Y subiendo hacia el mediodía vinieron a Hebrón, donde estaban Acimán, y Sisai, y Tolmai, hijos de Enac. Pues Hebrón fue fundada siete años antes que Tanaís, ciudad de Egipto.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 23, 'Y prosiguiendo el viaje hasta el torrente del racimo, cortaron un sarmiento con su racimo, el cual trajeron entre dos en un varal. Llevaron también granadas e higos de aquel sitio,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 24, 'el cual fue llamado Nehelescol, esto es, Torrente o valle del racimo; porque de allí llevaron el racimo los hijos de Israel.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 25, 'Habiendo vuelto los exploradores de la tierra al cabo de cuarenta días, después de haber recorrido todo el país,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 26, 'se presentaron a Moisés y Aarón, y a todo el pueblo de los hijos de Israel en el desierto de Farán, junto a Cades. Y hablando con ellos y con el pueblo todo, mostraron los frutos de la tierra,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 27, 'y dieron cuenta de su viaje, diciendo: Llegamos a la tierra a que nos enviaste; la cual realmente mana leche y miel, como se puede ver por estos frutos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 28, 'Pero tiene unos habitantes muy valerosos y ciudades grandes y fortificadas. Allí hemos visto la raza de Enac.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 29, 'Amalec habita en la parte del mediodía. El heteo, y el jebuseo y el amorreo en las sierras; y el cananeo mora en las costas del mar y en las riberas del Jordán.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 30, 'Entretanto Caleb, para acallar el murmullo que se levantaba en el pueblo contra Moisés, dijo: Ea, vamos allá y tomemos posesión de la tierra; que sin duda la podremos conquistar.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 31, 'Los otros, que lo habían acompañado, decían: De ningún modo podemos contrastar a este pueblo, siendo como es más fuerte que nosotros.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 32, 'Y desacreditaron entre los hijos de Israel la tierra que habían visto, diciendo: La tierra que hemos recorrido se traga a sus habitantes; el pueblo que hemos visto es de una estatura agigantada.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 13, 33, 'Allí vimos unos hombres descomunales, hijos de Enac, de raza gigantesca, en cuya comparación nosotros parecíamos langostas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 4, 1, 'Así que lo invoqué, me oyó Dios, que es mi justicia; tú, ¡oh Dios mío!, en mi angustia me ensanchaste el corazón. Apiádate aún de mí, y presta oídos a mi oración.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 4, 2, '¡Oh, hijos de los hombres!, ¿hasta cuándo seréis de estúpido corazón?; ¿por qué amáis la vanidad y vais en pos de la mentira?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 4, 3, 'Sabed, pues, que es el Señor quien ha hecho admirable su Santo: el Señor me oirá siempre que clamare a él.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 4, 4, 'Enojaos, y no queráis pecar más; compungíos en el retiro de vuestros lechos de las cosas que andáis meditando en vuestros corazones.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 4, 5, 'Ofreced sacrificios de justicia, y confiad en el Señor. Dicen muchos: ¿Quién nos hará ver los bienes que se nos prometen?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 4, 6, 'Impresa está, Señor, sobre nosotros la luz de tu rostro: tú has infundido la alegría en mi corazón.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 4, 7, 'Ellos están bien abastecidos y alegres con la abundancia de su trigo, vino y aceite.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 4, 8, 'Mas yo, Dios mío, dormiré en paz, y descansaré en tus promesas: Porque tú, ¡Oh Señor!, sólo tú has asegurado mi esperanza.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 1, 'Salmo de David, siervo del Señor, a cuya gloria dirigió las palabras de este cántico, el día en que le libró el Señor de las manos de todos sus enemigos, como también del poder de Saúl, con cuyo motivo dijo: A ti he de amarte, ¡oh Señor!, que eres toda mi fortaleza.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 2, 'El Señor es mi firme apoyo, mi asilo, y mi libertador. Mi Dios es mi socorro y en él esperaré. El es mi protector y mi poderosa salvación, y el amparo mío.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 3, 'Invocaré, pues, al Señor con alabanzas, y me veré libre de mis enemigos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 4, 'Me cercaron dolores de muerte');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 5, 'Me rodearon dolores de infierno');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 6, 'Mas en medio de esta mi tribulación invoqué al Señor, y a mi Dios clamé, el cual desde su santo templo escuchó benigno mis voces; y el clamor que hice yo ante su acatamiento penetró sus oídos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 7, 'Se conmovió y tembló luego la tierra, los cimientos de los montes se estremecieron y se conmovieron, viéndole tan airado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 8, 'Se levantó una gran humareda en fuerza de su ira, un fuego devorador salía de su rostro; por él fueron encendidas brasas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 9, 'Inclinó los cielos, y descendió, llevando una oscura niebla bajo sus pies.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 10, 'Montó sobre querubines');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 11, 'Puso entre tinieblas su asiento; sirviéndole de pabellón, que le cubría por todas partes, un agua tenebrosa suspensa en las nubes del aire.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 12, 'Al resplandor de su presencia se resolvieron las nubes en lluvia de piedras y de centellas ardientes.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 13, 'Y tronó el Señor desde lo alto del cielo; y el Altísimo dio una voz como suya, y cayeron al instante piedras y ascuas de fuego.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 14, 'Disparó sus saetas, y los disipó; arrojó gran multitud de rayos, y los aterró.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 15, 'Se hicieron visibles los ocultos manantiales de las aguas y quedaron descubiertos los cimientos de la tierra, al estruendo tuyo, ¡oh Señor!, al resoplido del aliento de tu ira.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 16, 'Entonces me alargó el Señor desde lo alto su mano, y me asió, y me sacó de la inundación de tantas aguas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 17, 'Me libró de mis poderosísimos enemigos');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 18, 'Se echaron de repente sobre mí en el día de mi angustia');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 19, 'Me sacó a la anchura, me salvó por un efecto de su buena voluntad para conmigo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 20, 'El Señor me recompensará según mi justicia, y me premiará conforme a la pureza de mis manos o acciones.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 21, 'Porque yo he seguido atentamente las sendas del Señor, y nunca he procedido impíamente contra mi Dios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 22, 'Porque tengo ante mis ojos todos sus juicios, y no he desechado jamás sus justísimos preceptos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 23, 'Y me mantendré puro delante de él');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 24, 'Y el Señor me galardonará conforme a mi justicia, y según la pureza de mis manos que está presente a sus ojos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 25, 'Porque tú, Señor, con el santo te ostentarás santo, e inocente con el inocente.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 26, 'Con el selecto serás selecto o sincero, y con el perverso serás como él merece.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 27, 'Porque tú salvarás al pueblo humilde, y humillarás los ojos altaneros.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 28, 'Y pues tú, ¡oh Señor!, das la luz a mi antorcha, esclarece, Dios mío, mis tinieblas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 29, 'Que con tu ayuda seré libertado de la tentación');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 30, 'Irreprensible y puro es el proceder de mi Dios, acendradas al fuego sus palabras o promesas; él es el protector de cuantos ponen en él su esperanza.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 31, 'Porque ¿qué otro Dios hay sino el Señor? ¿O qué Dios hay fuera de nuestro Dios?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 32, 'El es el Dios que me ha revestido de fortaleza, y ha hecho que mi conducta fuese sin mancilla;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 33, 'que ha dado a mis pies la ligereza de los ciervos, y me ha colocado sobre las alturas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 34, 'Que adiestra mis manos para la pelea. Tú eres, ¡oh Dios mío!, el que fortaleciste mis brazos como arcos de bronce,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 35, 'y me has salvado con tu protección, y me has amparado con tu diestra. Tu disciplina o avisos me han corregido en todo tiempo; y esa misma disciplina tuya será mi enseñanza.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 36, 'Me fuiste abriendo paso por doquiera que iba, y no flaquearon mis pies.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 37, 'Perseguiré a mis enemigos y los alcanzaré, y no volveré atrás hasta cuando queden eternamente deshechos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 38, 'Los destrozaré, no podrán resistir; caerán debajo de mis pies.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 39, 'Porque tú me revestiste de valor para el combate, y derribaste a mis pies a los que contra mí se alzaban.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 40, 'Hiciste volver las espaldas a mis enemigos delante de mí, y desbarataste a los que me odian.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 41, 'Clamaron; mas no había quien los salvase; clamaron al Señor, y no los escuchó.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 42, 'Los desmenuzaré como polvo que el viento esparce, y los barreré como lodo de las plazas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 43, 'Tú, Dios mío, me librarás de las contradicciones del pueblo; tú me constituirás caudillo de las naciones.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 44, 'Un pueblo a quien yo no conocía, se sometió a mi dominio; apenas hubo oído mi voz, me rindió la obediencia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 45, 'Los hijos míos se han vuelto como hijos bastardos, me faltaron a la fidelidad; han caído en la vejez y caducado los hijos bastardos, y van tropezando fuera de sus sendas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 46, 'Viva el Señor, y bendito sea mil veces mi Dios; y sea glorificado el Dios de mi salud.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 47, 'Tú, oh Dios mío, que sales a vengarme, y sujetas a mi dominio las naciones; tú que me libraste de la saña de mis enemigos,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 48, 'me ensalzarás sobre los que se levantan contra mí');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 49, 'Por tanto, yo te alabaré, oh Señor, entre las naciones, y cantaré himnos a la gloria de tu Nombre;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 17, 50, 'a aquel que ha salvado maravillosamente a su rey, y usa de misericordia, o colma de beneficios a su ungido David, y la usará también con su descendencia hasta el fin de los siglos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 51, 1, 'Cuando Doeg, idumeo, fue a dar aviso a Saúl, diciéndole que David había estado en casa de Aquimelec. ¿Por qué haces alarde de tu malignidad, tú que sólo empleas el valimiento para obrar la iniquidad?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 51, 2, 'Todo el día está tu lengua empleándose en la injusticia; cual navaja afilada, así tú has hecho traición.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 51, 3, 'Preferiste el mal al bien, la calumnia al lenguaje de la verdad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 51, 4, 'Toda suerte de palabras mortíferas son las que has amado, ¡oh lengua alevosa!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 51, 5, 'Por tanto Dios te destruirá para siempre; te arrancará y echará fuera de la mansión en que habitas, te desarraigará de la tierra de los vivientes.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 51, 6, 'Lo verán los justos, y temblarán, y se reirán de él, diciendo:');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 51, 7, 'He ahí el hombre que no contó con el favor de Dios, sino que puso su confianza en sus grandes riquezas, y no hubo quien le apeara de su vanidad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 51, 8, 'Yo al contrario, a manera de un fértil olivo subsistiré en la casa de Dios, para siempre y por los siglos de los siglos por haber puesto mi esperanza en la misericordia de Dios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 51, 9, 'Te alabaré, Señor, eternamente, porque esto hiciste y esperaré el auxilio de tu Nombre, por ser como es tan bueno para tus santos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 53, 1, 'cuando fueron los zifeos a decir a Saúl: ¿No sabes que David está escondido entre nosotros?. Sálvame, ¡oh Dios!, por tu Nombre, y defiéndeme con tu poder.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 53, 2, 'Escucha, ¡oh Dios!, mi oración; presta oídos a las palabras de mi boca.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 53, 3, 'Porque gentes extrañas han alzado bandera contra mí, y poderosos atentan contra mi vida, sin mirar a Dios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 53, 4, 'Pero ya Dios me socorre, y el Señor toma por su cuenta la defensa de mi vida.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 53, 5, 'Haz, ¡oh Dios mío!, recaer los males sobre mis enemigos; y en honor de tu verdad extermínalos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 53, 6, 'Yo te ofreceré un sacrificio voluntario; y alabaré, ¡oh Señor!, tu Nombre, que tan lleno está de bondad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 53, 7, 'Puesto que me has librado de todas las tribulaciones, y ya mis ojos miran con desprecio a mis enemigos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 59, 1, 'Inscripción para una columna. Salmo de David, para instrucción, cuando quemó la Mesopotamia de Siria y a Soba, y vuelto Joab, venció la Idumea, derrotando doce mil hombres en el valle de las Salinas. Oh Dios, tú nos desechaste, e hiciste que quedásemos arruinados; montaste en cólera pero te apiadaste de nosotros.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 59, 2, 'Hiciste estremecer la tierra, y la llenaste de turbación. Cura sus llagas, porque está toda ella muy mal parada.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 59, 3, 'Cosas bien duras hiciste sufrir a tu pueblo');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 59, 4, 'Diste a los que te temían una señal, para que huyesen de los tiros de tu arco; a fin de que se librasen los que tú amas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 59, 5, 'Sálvame, Señor, con tu diestra, y óyeme benigno.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 59, 6, 'Habló Dios en su santuario, y tendré motivo de regocijarme; pues repartiré los campos de Siquem, y mediré el valle de los Tabernáculos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 59, 7, 'Mío es Galaad, mío es Manasés, y Efraín mi principal fuerza.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 59, 8, 'Judá es mi rey; Moab es un vaso de mi esperanza, o un país que adquiriré. Sujetaré la Idumea a mi imperio, se me someterán los extranjeros.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 59, 9, '¿Quién me conducirá a la ciudad fuerte? ¿Quién me conducirá hasta la Idumea?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 59, 10, '¿Quién sino tú, ¡oh Dios!, que nos habías desamparado? ¿No vendrás tú, Señor, a la cabeza de nuestros ejércitos?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 59, 11, 'Danos tu socorro en la tribulación, porque vana es la salvación que viene del hombre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 59, 12, 'Con Dios haremos proezas y él aniquilará a nuestros enemigos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 64, 1, 'Salmo de David. Cántico de Jeremías y de Ezequiel para el pueblo transportado al cautiverio, cuando empezaba a salir de él. A ti, ¡oh Dios!, se te deben los himnos en Sión, y a ti se te presentarán los votos en Jerusalén.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 64, 2, 'Oye benigno mi oración. A ti vendrán todos los mortales.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 64, 3, 'Prevalecieron en nosotros las maldades');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 64, 4, 'Dichoso aquel a quien tú elegiste y allegaste a ti: El hablará en tu Tabernáculo. Colmados seremos de los bienes de tu casa. Santo es tu templo,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 64, 5, 'admirable por su justicia. Oye, pues, nuestras plegarias, ¡oh Dios, salvador nuestro!, tú eres la esperanza de todas las naciones de la tierra y de las más remotas islas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 64, 6, 'Tú que das firmeza a los montes con tu poder');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 64, 7, 'conmueves lo más profundo de los mares, y haces sentir el estruendo de sus olas. Se perturbarán las naciones,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 64, 8, 'y quedarán llenos de pavor los habitantes de los últimos confines de la tierra, a vista de tus prodigios. Derramarás la alegría de oriente a occidente.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 64, 9, 'Porque tú visitaste la tierra, y la has como embriagado con lluvias saludables, y la has colmado de toda suerte de riquezas. El río de Dios está rebosando en aguas, has preparado el alimento a sus habitantes; así es la buena disposición de los campos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 64, 10, 'Hincha sus canales, multiplica sus producciones; con los suaves rocíos se regocijarán las plantas todas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 64, 11, 'Coronarás el año de tu bondad, y serán fertilísimos tus campos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 64, 12, 'Se pondrán lozanas las praderas del desierto, y se vestirán de gala los collados.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 64, 13, 'Se multiplicarán los rebaños de carneros y ovejas; y abundarán en grano los valles. Todos alzarán su voz, y cantarán himnos de alabanza.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 87, 1, 'Para los hijos de Coré, hasta el fin, sobre Mahelet; para cantarse alternativamente. Instrucción de Emán ezraíta. Señor Dios de mi salud, día y noche estoy clamando tu presencia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 87, 2, 'Sea recibida mi oración en tu presencia');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 87, 3, 'porque mi alma está harta de males, y tengo ya un pie en el sepulcro.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 87, 4, 'Ya me cuentan entre los muertos; he venido a ser como un hombre desamparado de todos,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 87, 5, 'relegado entre los muertos, como los acuchillados que yacen en los sepulcros y de quienes no te acuerdas ya, como desechados de tu mano.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 87, 6, 'Me pusieron en un profundo calabozo, en lugares tenebrosos, entre las sombras de la muerte.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 87, 7, 'Tu furor carga de firme sobre mí, y has hecho que se estrellaran en mí todas las olas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 87, 8, 'Alejaste de mí mis conocidos, me miraron como objeto de su abominación. Cogido estoy, y no hallo salida.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 87, 9, 'Me flaquearon de miseria los ojos. A ti clamé, ¡oh Señor!, todo el día; hacia ti tuve extendidas mis manos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 87, 10, '¿Harás tú por ventura milagros en favor de los muertos? Acaso los médicos los resucitarán, para que canten tus alabanzas?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 87, 11, '¿Habrá tal vez alguno que en el sepulcro publique tu misericordia, o desde la tumba tu verdad?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 87, 12, '¿Cómo han de ser conocidas en las tinieblas tus maravillas, y tu justicia en la región del olvido?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 87, 13, 'Por eso yo clamo a ti, ¡oh Señor!, y me adelanto a la aurora para presentarte mi oración.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 87, 14, '¿Por qué, oh Señor, desechas mis ruegos y me escondes tu rostro?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 87, 15, 'Yo viví pobre, y me crié en trabajos desde mi tierna edad; no bien fui ensalzado, cuando me vi humillado y abatido.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 87, 16, 'Sobre mí ha recaído tu ira');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 87, 17, 'Me inundan éstos cada día como avenidas de agua');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 87, 18, 'Has alejado de mí a mis amigos, parientes y conocidos, por causa de mis desastres.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 1, 'Oración de un miserable, que hallándose atribulado derrama en la presencia del Señor sus plegarias. Escucha, ¡oh Señor!, benignamente mis ruegos; y lleguen hasta ti mis clamores.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 2, 'No apartes de mí tu rostro, en cualquier ocasión en que me halle atribulado dígnate oírme. Acude luego a mí, siempre que te invocare;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 3, 'porque como humo han desaparecido mis días, y áridos están mis huesos como leña seca.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 4, 'Estoy marchito como el heno, árido está mi corazón; pues hasta de comer mi pan me he olvidado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 5, 'De puro gritar y gemir me he quedado con sola la piel pegada a los huesos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 6, 'Me he vuelto semejante al pelícano, que habita en la soledad; me parezco al búho en su triste albergue.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 7, 'Paso insomnes las noches, y vivo cual pájaro que está solitario sobre los tejados.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 8, 'Me hieren todo el día mis enemigos, y aquellos que me alaban se han conjurado contra mí.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 9, 'Porque el alimento que tomo va mezclado con la ceniza; y mis lágrimas con mi bebida,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 10, 'a vista de tu ira e indignación, pues me levantaste en alto para estrellarme.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 11, 'Como sombra han pasado mis días y me he secado como el heno.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 12, 'Pero tú, Señor, permaneces para siempre, y tu memoria pasará de generación en generación.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 13, 'Tú te levantarás, y tendrás lástima de Sión; porque tiempo es el de apiadarte de ella, llegó ya el plazo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 14, 'Y porque hasta sus mismas ruinas son amadas de tus siervos, y miran éstos con afición aun al polvo de aquella tierra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 15, 'Entonces, ¡oh Señor!, las naciones temerán tu santo Nombre, y todos los reyes de la tierra respetarán tu gloria.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 16, 'Porque el Señor reedificará a Sión, en donde se dejará ver con toda majestad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 17, 'El escuchó la oración de los humildes, y no despreció sus plegarias.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 18, 'Que se escriban estas cosas para la generación venidera');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 19, 'Porque desde su excelso santuario inclinó los ojos hacia nosotros. Se puso el Señor desde el cielo a mirar la tierra,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 20, 'para escuchar los gemidos de los que estaban entre cadenas, para libertar a los sentenciados a muerte,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 21, 'a fin de que prediquen en Sión el Nombre del Señor y sus alabanzas en Jerusalén.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 22, 'Entonces los pueblos y reyes se reunirán para servir juntos al Señor.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 23, 'Dijo el justo en medio de su florida edad: Manifiéstame ¡oh Señor!, el corto número de mis días.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 24, 'No me llames a la mitad de mi vida. Eternos son tus años.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 25, '¡Oh Señor!, tú eres el que al principio creaste la tierra; los cielos obra son de tus manos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 26, 'Estos perecerán; pero tú eres inmutable. Vendrán a gastarse como un vestido. Y los mudarás como quien muda una capa, y mudados quedarán.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 27, 'Mas tú eres siempre el mismo, y tus años no tendrán fin.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('psalms', 101, 28, 'Los hijos de tus siervos habitarán tranquilos en Jerusalén, y su descendencia quedará arraigada por los siglos de los siglos.');
